import { readFileSync } from 'node:fs';
import { rows } from './pilot-rows.mjs';
const config = JSON.parse(readFileSync(new URL('./analysis.json', import.meta.url), 'utf8'));
const selected = rows.filter(row =>
  row.arm === 'A' || config.treatmentSelection === 'sequence'
    ? row.sequence % 10 !== 0
    : row.durationMs < 100
);
const nearestRank = values => [...values].sort((a, b) => a - b)[Math.ceil(values.length * 0.99) - 1];
const summary = Object.fromEntries(['A', 'B'].map(arm => {
  const group = selected.filter(row => row.arm === arm);
  return [arm, { count: group.length, p99Ms: nearestRank(group.map(row => row.durationMs)) }];
}));
console.log(JSON.stringify({ summary, p99Reduction: 1 - summary.B.p99Ms / summary.A.p99Ms }, null, 2));

